USE maison_valmont;

TRUNCATE TABLE ventes;
TRUNCATE TABLE budget;
TRUNCATE TABLE calendrier;
TRUNCATE TABLE vendeurs;
TRUNCATE TABLE clients;
TRUNCATE TABLE produits;
TRUNCATE TABLE magasins;

