SELECT 'magasins' AS table_, COUNT(*) AS nb FROM magasins UNION ALL
SELECT 'produits',   COUNT(*) FROM produits   UNION ALL
SELECT 'clients',    COUNT(*) FROM clients    UNION ALL
SELECT 'vendeurs',   COUNT(*) FROM vendeurs   UNION ALL
SELECT 'calendrier', COUNT(*) FROM calendrier UNION ALL
SELECT 'budget',     COUNT(*) FROM budget     UNION ALL
SELECT 'ventes',     COUNT(*) FROM ventes;


-- ETAPE 4 : les canaux
SELECT Canal, COUNT(*) AS nb_ventes, SUM(CA_vente) AS chiffre_affaires
FROM ventes
GROUP BY Canal;

